-- -------------------------------------------------------------------------
--  ASSERTIONS
--
--  Not "did the CREATE statements run" — that much a syntax error
--  would catch. These prove the PROPERTIES the staging layer exists
--  for: nothing can reject a row. A NOT NULL, a default or a check
--  on a source column would each turn a load failure into a lost
--  row, and none of them would look wrong in a diff.
-- -------------------------------------------------------------------------

DO $STAGING$
DECLARE
    n integer;
BEGIN
    SELECT count(*) INTO n FROM information_schema.tables
     WHERE table_schema = 'staging' AND table_type = 'BASE TABLE';
    IF n <> 20 THEN
        RAISE EXCEPTION 'staging: % tables, expected 20', n;
    END IF;

    SELECT count(*) INTO n FROM information_schema.columns
     WHERE table_schema = 'staging';
    IF n <> 244 THEN
        RAISE EXCEPTION 'staging: % columns, expected 244 (204 from Access + 20 x 2 bookkeeping)', n;
    END IF;

    --  Every source column is text. A typed column here would be a
    --  column that can refuse a row.
    SELECT count(*) INTO n FROM information_schema.columns
     WHERE table_schema = 'staging'
       AND column_name NOT IN ('src_file', 'src_row_num')
       AND data_type <> 'text';
    IF n <> 0 THEN
        RAISE EXCEPTION 'staging: % source columns are not text', n;
    END IF;

    --  ...and every one of them is nullable, so NULL and '' can both
    --  arrive and stay different.
    SELECT count(*) INTO n FROM information_schema.columns
     WHERE table_schema = 'staging'
       AND column_name NOT IN ('src_file', 'src_row_num')
       AND is_nullable <> 'YES';
    IF n <> 0 THEN
        RAISE EXCEPTION 'staging: % source columns are NOT NULL', n;
    END IF;

    --  No defaults. A default would invent a value for a field the
    --  firm left empty, which is the opposite of what staging is for.
    SELECT count(*) INTO n FROM information_schema.columns
     WHERE table_schema = 'staging' AND column_default IS NOT NULL;
    IF n <> 0 THEN
        RAISE EXCEPTION 'staging: % columns have a default', n;
    END IF;

    --  No checks anywhere in the schema.
    SELECT count(*) INTO n
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace ns ON ns.oid = t.relnamespace
     WHERE ns.nspname = 'staging' AND c.contype = 'c';
    IF n <> 0 THEN
        RAISE EXCEPTION 'staging: % check constraints', n;
    END IF;

    --  No foreign keys either. A staging row that fails to find its
    --  parent is a finding for Gate 3, not a load error.
    SELECT count(*) INTO n
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace ns ON ns.oid = t.relnamespace
     WHERE ns.nspname = 'staging' AND c.contype = 'f';
    IF n <> 0 THEN
        RAISE EXCEPTION 'staging: % foreign keys', n;
    END IF;

    --  Every table keyed on the bookkeeping pair, so loading the same
    --  file twice is an error rather than a silent doubling.
    SELECT count(*) INTO n
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace ns ON ns.oid = t.relnamespace
     WHERE ns.nspname = 'staging' AND c.contype = 'p';
    IF n <> 20 THEN
        RAISE EXCEPTION 'staging: % primary keys, expected 20', n;
    END IF;

    RAISE NOTICE 'staging: 20 tables, 204 source columns, all text, nothing can refuse a row';
END
$STAGING$;
